// checkout — сценарий над доменами
checkout = async (cart) => {
  ok = await billing.authorize(cart.customerId, cart.total)
  if (!ok) throw new PaymentDeclined()
  return orders.place(cart)
}

// orders/ports
interface CreditCheck { canSpend(id: CustomerId, sum: Money): Promise<boolean> }

// adapters/orders-to-billing — единственное место, знающее обоих
class BillingCreditCheck implements CreditCheck {
  canSpend(id, sum) = billingApi.authorize(id, sum).then(r => r.status == "ok")
}

// orders — только публикует факт
await events.publish(OrderPlaced { orderId, items })

// warehouse — сам решает, что делать
on OrderPlaced (e) { await stock.writeOff(e.items) }
